// ── Set this to your deployed LeadFlow URL (no trailing slash) ──
const LEADFLOW_BASE_URL = 'https://leadflow-ten-beta.vercel.app';
const GEMINI_MODEL = 'gemini-3.7-flash';

// The app posts a flat lead object; n8n wraps it under `body`.
const lead = $json.body ?? $json;
const email = String(lead.email || '');
const domain = email.split('@')[1] || '';

const clean = {
  leadflow_base_url: LEADFLOW_BASE_URL,
  lead_id: lead.id,
  name: lead.name || '',
  email,
  company: lead.company || domain || '',
  domain,
  team_size: Number(lead.team_size ?? 0),
  budget: Number(lead.budget ?? 0),
  timeline: Number(lead.timeline ?? 0),
  message: lead.message || '',
  app_score: lead.score ?? null,
};

const prompt = [
  'You are a B2B sales qualification engine. Score inbound leads 0-100 on how likely they are to buy soon.',
  '',
  'Apply this rubric. Start at 30, then:',
  '- Budget (monthly USD): >=50000 +28, >=10000 +22, >=2000 +14, >=500 +6, else +0.',
  '- Team size: >=200 +16, >=50 +11, >=10 +6.',
  '- Timeline (0 research .. 3 urgent): 3 +18, 2 +12, 1 +6.',
  '- Business email +8; free email (gmail/yahoo/hotmail/outlook/icloud/proton) -6.',
  '- Pain keywords in the message (manual, hours, waste, copy, paste, spreadsheet, urgent, asap, slow, error, hire, scale, integrate, automate): +4 each, capped at +12. Name the matched words in the reason.',
  'Clamp the final score to 2-99. Temperature: hot >= 70, warm 45-69, cold < 45.',
  '',
  'Score this lead:',
  'Name: ' + clean.name,
  'Email: ' + clean.email,
  'Company: ' + clean.company,
  'Team size: ' + clean.team_size,
  'Monthly budget (USD): ' + clean.budget,
  'Timeline code (0 research .. 3 urgent): ' + clean.timeline,
  'Message: ' + clean.message,
].join('\n');

const payload = {
  model: GEMINI_MODEL,
  input: prompt,
  response_format: {
    type: 'text',
    mime_type: 'application/json',
    schema: {
      type: 'object',
      properties: {
        score: { type: 'integer', description: 'Final score, 2-99.' },
        temperature: { type: 'string', enum: ['hot', 'warm', 'cold'] },
        reason: { type: 'string', description: 'One sentence explaining the score.' },
      },
      required: ['score', 'temperature', 'reason'],
    },
  },
};

return [{ json: { ...clean, payload } }];

// Pull the model's JSON out of whichever response envelope came back.
const lead = $('Normalize Fields').item.json;
const res = $json;

let text = '';
if (typeof res.output_text === 'string') {
  text = res.output_text;
} else if (Array.isArray(res.steps)) {
  text = res.steps
    .flatMap((s) => s.content || [])
    .filter((b) => typeof b.text === 'string')
    .map((b) => b.text)
    .join('');
} else if (Array.isArray(res.candidates)) {
  text = (res.candidates[0]?.content?.parts || [])
    .filter((p) => typeof p.text === 'string')
    .map((p) => p.text)
    .join('');
}

let ai = null;
try {
  ai = JSON.parse(text);
} catch (e) {
  ai = null;
}

const rawScore = Number(ai?.score);
const ai_ok = ai !== null && Number.isFinite(rawScore);

const score = ai_ok ? Math.max(2, Math.min(99, Math.round(rawScore))) : lead.app_score;
const temperature = ai_ok
  ? (['hot', 'warm', 'cold'].includes(ai.temperature)
      ? ai.temperature
      : score >= 70 ? 'hot' : score >= 45 ? 'warm' : 'cold')
  : (score >= 70 ? 'hot' : score >= 45 ? 'warm' : 'cold');
const reason = ai_ok ? String(ai.reason || '').trim() : 'Gemini unavailable — kept the app\u2019s rubric score.';

// Only overwrite the app's score when Gemini actually answered. A failed call
// must never downgrade a good lead — it just marks it synced.
const patch = ai_ok
  ? { score, temperature, ai_reason: reason, status: 'synced' }
  : { status: 'synced' };

const ghl = {
  locationId: 'YOUR_GHL_LOCATION_ID',
  name: lead.name,
  email: lead.email,
  companyName: lead.company,
  tags: ['leadflow', temperature, 'ai-score-' + score],
  customFields: [
    { key: 'ai_score', field_value: String(score) },
    { key: 'ai_reason', field_value: reason },
  ],
};

const slack_text = [
  ':fire: *HOT lead* — ' + lead.name + ' (' + lead.company + ')',
  'Score: *' + score + '/100* — ' + reason,
  'Email: ' + lead.email + ' | Budget: ' + lead.budget + ' | Timeline: ' + lead.timeline,
].join('\n');

return [{ json: { ...lead, score, temperature, reason, ai_ok, patch, ghl, slack_text } }];
